1. //! `derrick uninstall` — reverse the effects of `derrick init`.
2. //!
3. //! Removes `derrick.yaml`, the `.derrick/` state directory, and the derrick
4. //! block from `.codex/instructions.md`. Does not touch `.claude/settings.json`
5. //! (the hook config) in v1 — a note is printed instead.
6. 
7. use std::path::Path;
8. 
9. use crate::commands::UninstallArgs;
10. use crate::exit_code::CliExitCode;
11. use crate::{current_repo_root, message};
12. 
13. pub(crate) async fn execute(args: UninstallArgs) -> Result<CliExitCode, crate::CliError> {
14.     let _ = args.purge; // reserved for future use; accepted for forward-compat.
15.     let repo_root = current_repo_root()?;
16.     let config_path = repo_root.join("derrick.yaml");
17.     let state_dir = repo_root.join(".derrick");
18.     let codex_instructions = repo_root.join(".codex/instructions.md");
19. 
20.     // Summarise what will be removed.
21.     let mut will_remove: Vec<String> = Vec::new();
22.     if config_path.exists() {
23.         will_remove.push(config_path.display().to_string());
24.     }
25.     if state_dir.exists() {
26.         will_remove.push(state_dir.display().to_string());
27.     }
28.     if codex_instructions.exists() {
29.         will_remove.push(format!(
30.             "{} (derrick block stripped)",
31.             codex_instructions.display()
32.         ));
33.     }
34. 
35.     if will_remove.is_empty() {
36.         println!("nothing to remove — no derrick installation found");
37.         return Ok(CliExitCode::Success);
38.     }
39. 
40.     println!("will remove:");
41.     for item in &will_remove {
42.         println!("  {item}");
43.     }
44.     println!(
45.         "note: .claude/settings.json hook entries are not removed automatically in v1;\n\
46.          remove the derrick hooks block manually if desired."
47.     );
48. 
49.     if !args.yes {
50.         print!("proceed? [y/N] ");
51.         use std::io::Write as _;
52.         let _ = std::io::stdout().flush();
53.         let mut answer = String::new();
54.         std::io::stdin()
55.             .read_line(&mut answer)
56.             .map_err(|e| message(e.to_string()))?;
57.         if !answer.trim().eq_ignore_ascii_case("y") {
58.             println!("aborted");
59.             return Ok(CliExitCode::Success);
60.         }
61.     }
62. 
63.     remove_items(&repo_root, &config_path, &state_dir)?;
64.     Ok(CliExitCode::Success)
65. }
66. 
67. fn remove_items(
68.     repo_root: &Path,
69.     config_path: &Path,
70.     state_dir: &Path,
71. ) -> Result<(), crate::CliError> {
72.     if config_path.exists() {
73.         std::fs::remove_file(config_path).map_err(|e| crate::CliError::Io {
74.             path: config_path.to_path_buf(),
75.             source: e,
76.         })?;
77.         println!("removed  {}", config_path.display());
