 use assert_cmd::Command;
 use tempfile::TempDir;

 type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;

 fn derrick() -> TestResult<Command> {
     Ok(Command::cargo_bin("derrick")?)
 }

 fn repo() -> TestResult<TempDir> {
